// The tray calls window.pasteget.show() with what to display (desktop/tray/src/pairing.rs).
// Text from devices and errors goes in with textContent only.
"use strict";

window.pasteget = {
  show(view) {
    const code = document.getElementById("code");
    const status = document.getElementById("status");
    status.className = "status";
    switch (view.kind) {
      case "code":
        code.className = "code";
        // The SVG is generated by the tray from the pairing link, never from a peer.
        code.innerHTML = view.svg;
        status.textContent = window.pastegetFrench
          ? `Le code ne sert qu'une fois, pendant ${view.minutes} minutes. Garde-le pour toi : ` +
            "le premier qui le scanne est appairé."
          : `The code works once, for ${view.minutes} minutes. Keep it to yourself: ` +
            "whoever scans it first is paired.";
        break;
      case "attempt-failed":
        status.className = "status bad";
        status.textContent = window.pastegetFrench
          ? `Un appareil a essayé de s'appairer, sans succès : ${view.text}`
          : `A device tried to pair but failed: ${view.text}`;
        break;
      case "paired":
        code.className = "code done";
        code.textContent = "✓";
        status.className = "status ok";
        status.textContent = window.pastegetFrench
          ? `Appairé avec ${view.text}.`
          : `Paired with ${view.text}.`;
        break;
      case "error":
        code.className = "code failed";
        code.textContent = "!";
        status.className = "status bad";
        status.textContent = window.pastegetFrench
          ? `${view.text}. Ferme cette fenêtre et choisis à nouveau « Appairer un téléphone… ».`
          : `${view.text}. Close this window and choose “Pair a phone…” again.`;
        break;
    }
  },
};
